        dx = x2 - x1
        dy = y2 - y1

        distance = math.hypot(dx, dy)

        if distance == 0:
            continue

        ux = dx / distance
        uy = dy / distance

        start_x = x1 + ux * (node_radius + 5)
        start_y = y1 + uy * (node_radius + 5)

        end_x = x2 - ux * (node_radius + 10)
        end_y = y2 - uy * (node_radius + 10)

        if value == 2:
            color = "#e53935"
            marker = "red"
            width = 3

        elif value == 0.5:
            color = "#1565c0"
            marker = "blue"
            width = 2

        else:
            color = "#333333"
            marker = "black"
            width = 2

        svg += f"""
