daily = data["daily"]
temps_by_year = {}
hot_days_by_year = {}

for day, temp in zip(daily["time"], daily["temperature_2m_max"]):
    month = int(day[5:7])
    year = int(day[:4])

    # 夏は6月・7月・8月
    if month in (6, 7, 8) and temp is not None:
        temps_by_year.setdefault(year, []).append(temp)
        if temp >= 35:
            hot_days_by_year[year] = hot_days_by_year.get(year, 0) + 1
        else:
            hot_days_by_year.setdefault(year, 0)

print("年 | 夏の日最高気温の平均(℃) | 最高気温35℃以上の日数")
print("-" * 58)

for year in sorted(temps_by_year):
    temps = temps_by_year[year]
    avg_temp = sum(temps) / len(temps)
    hot_days = hot_days_by_year.get(year, 0)
    print(f"{year} | {avg_temp:.2f} | {hot_days}")

yearly_avg = {
    year: sum(temps) / len(temps)
    for year, temps in temps_by_year.items()
}

if yearly_avg:
    hottest_year = max(yearly_avg, key=yearly_avg.get)
    coolest_year = min(yearly_avg, key=yearly_avg.get)

    print(f"夏の日最高気温の平均が最も高かった年：{hottest_year}年（{yearly_avg[hottest_year]:.2f}℃）")
    print(f"夏の日最高気温の平均が最も低かった年：{coolest_year}年（{yearly_avg[coolest_year]:.2f}℃）")

    first = [yearly_avg[y] for y in yearly_avg if 2016 <= y <= 2020]
    second = [yearly_avg[y] for y in yearly_avg if 2021 <= y <= 2025]
    if first and second:
        first_avg = sum(first) / len(first)
        second_avg = sum(second) / len(second)
        print(f"2016〜2020年の平均：{first_avg:.2f}℃")
        print(f"2021〜2025年の平均：{second_avg:.2f}℃")
        print(f"後半と前半の差：{second_avg - first_avg:+.2f}℃")
else:
    print("集計データがありません。最初のセルが成功したか確認してください。")

